#!/bin/sh
PATH=/usr/bin:/bin
export PATH
LC_ALL=C
export LC_ALL

event_version=1
collector=node_meminfo_v1
memory_node_count=0
discovered_node_count=0

for path in /sys/devices/system/node/node[0-9]*/meminfo; do
    [ -e "$path" ] || continue
    discovered_node_count=$((discovered_node_count + 1))
    [ -r "$path" ] || continue
    mem_total_kb=$(awk '$1=="Node" && $3=="MemTotal:" && $4~/^[0-9]+$/ && $5=="kB" {print $4; exit}' "$path")
    case "$mem_total_kb" in
        ''|*[!0-9]*) ;;
        *) [ "$mem_total_kb" -gt 0 ] && memory_node_count=$((memory_node_count + 1)) ;;
    esac
done

if [ "$discovered_node_count" -eq 0 ]; then
    printf 'event_version=%s collector=%s event_type=collector_error collection_status=error error_code=no_node_meminfo_files\n' "$event_version" "$collector"
    exit 0
fi

if [ "$memory_node_count" -lt 2 ]; then
    printf 'event_version=%s collector=%s event_type=collector_error collection_status=error error_code=fewer_than_two_memory_nodes expected_node_count=%s discovered_node_count=%s\n' "$event_version" "$collector" "$memory_node_count" "$discovered_node_count"
    exit 0
fi

for path in /sys/devices/system/node/node[0-9]*/meminfo; do
    [ -e "$path" ] || continue
    node=${path%/meminfo}
    node=${node##*/node}
    if [ ! -r "$path" ]; then
        printf 'event_version=%s collector=%s event_type=collector_error collection_status=error error_code=node_meminfo_unreadable numa_node=%s expected_node_count=%s\n' "$event_version" "$collector" "$node" "$memory_node_count"
        continue
    fi
    awk -v node="$node" -v expected="$memory_node_count" -v version="$event_version" -v collector="$collector" '
      $1=="Node" && $2==node && ($3=="MemTotal:" || $3=="MemFree:" || $3=="MemUsed:") && $4~/^[0-9]+$/ && $5=="kB" {
          key=$3; sub(/:$/, "", key); value[key]=$4
      }
      END {
          prefix="event_version=" version " collector=" collector
          if (!("MemTotal" in value) || !("MemFree" in value) || !("MemUsed" in value)) {
              printf "%s event_type=collector_error collection_status=error error_code=missing_or_nonnumeric_meminfo_field numa_node=%s expected_node_count=%s\n", prefix, node, expected
          } else if (value["MemTotal"]==0) {
              printf "%s event_type=node_inventory collection_status=not_applicable reason=zero_memtotal numa_node=%s expected_node_count=%s\n", prefix, node, expected
          } else if (value["MemFree"]>value["MemTotal"] || value["MemUsed"]>value["MemTotal"] || value["MemUsed"]!=value["MemTotal"]-value["MemFree"]) {
              printf "%s event_type=collector_error collection_status=error error_code=inconsistent_meminfo_values numa_node=%s expected_node_count=%s\n", prefix, node, expected
          } else {
              printf "%s event_type=node_sample collection_status=ok numa_node=%s expected_node_count=%s mem_total_kb=%s mem_free_kb=%s mem_used_kb=%s\n", prefix, node, expected, value["MemTotal"], value["MemFree"], value["MemUsed"]
          }
      }
    ' "$path"
done
